package app.staysound.core.model

import java.net.URLDecoder
import java.util.Locale

/** A file reported by the MediaStore/SAF scan. [filename] is MediaStore's DISPLAY_NAME (JS: `track._filename`). */
data class ScannedTrack(val track: Track, val filename: String? = null)

/**
 * Port of `src/services/scanReconcile.ts`. It decides which scanned files are junk and how the ones that match a
 * track the library already knows keep their metadata. Parity with the JavaScript is checked against golden
 * fixtures generated by running that TypeScript (see `scripts/generate-scan-golden.ts`), so change both together.
 *
 * Deliberate difference: JavaScript's `decodeURIComponent` throws on a malformed escape and aborts the whole scan;
 * here an undecodable value is used as-is so one odd file name cannot stop a scan.
 */
object ScanReconciler {
    /** Extension key that carries `_filename` through the legacy JSON, which the playback fallback needs. */
    const val FILENAME_KEY = "_filename"

    private val genericLibraryValues = setOf("unknown", "unknown title", "unknown artist", "unknown album", "media", "external", "staysound")
    private val genericParentFolders = setOf("0", "download", "downloads", "music", "musica", "música", "audio", "documents", "documentos", "staysound", "media", "external")
    private val extension = Regex("\\.[^/.]+$")
    private val audioSuffix = Regex("\\.(flac|mp3|m4a|aac|wav|ogg|opus)(?:$|\\?)", RegexOption.IGNORE_CASE)
    private val trackNumberPrefix = Regex("^\\d+[$JS_SPACE._-]*")
    private val leadingDashes = Regex("^[-—–$JS_SPACE]+")
    private val separator = Regex(" [-—–] ")
    private val reserved = Regex("[<>:\"/\\\\|?*]")
    private val spaces = Regex("$JS_SPACE_CLASS+")
    private val numeric = Regex("^\\d+$")

    // JavaScript's \s and String.trim() treat NBSP, BOM and the Unicode space separators as whitespace.
    private const val JS_SPACE = "\\s\\u00a0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000\\ufeff"
    private const val JS_SPACE_CLASS = "[$JS_SPACE]"
    private fun Char.isJsSpace() = this in "\t\u000b\u000c \u00a0\ufeff\n\r\u2028\u2029" || Character.getType(this) == Character.SPACE_SEPARATOR.toInt()
    private fun String.jsTrim() = trim { it.isJsSpace() }
    private fun String.lower() = lowercase(Locale.ROOT)

    private fun decode(value: String): String = try {
        URLDecoder.decode(value.replace("+", "%2B"), Charsets.UTF_8)
    } catch (_: IllegalArgumentException) { value }

    fun hasMeaningfulValue(value: String?): Boolean {
        val normalized = value?.jsTrim()?.lower()
        return !normalized.isNullOrEmpty() && normalized !in genericLibraryValues
    }

    fun isMediaStoreAlbumArt(uri: String?) = uri != null && uri.startsWith("content://media/external/audio/albumart/")

    private fun pathForJunkCheck(value: String?) = decode(value.orEmpty()).lower().replace('\\', '/')

    private fun isCacheDownload(uri: String?): Boolean {
        val normalized = pathForJunkCheck(uri)
        return normalized.contains("/cache/staysound/downloads/") || (normalized.contains("/android/data/") && normalized.contains("/cache/"))
    }

    fun isLikelyJunk(track: Track, filename: String?): Boolean {
        val combined = listOf(track.uri, track.relativePath, filename).joinToString("/") { pathForJunkCheck(it) }
        if (!(combined.contains("staysound") || track.source == "tidal")) return false
        if (isCacheDownload(track.uri) || isCacheDownload(track.relativePath)) return true
        return audioSuffix.containsMatchIn(filename ?: track.uri) && track.duration <= 0
    }

    fun resolveArtwork(scanned: String?, existing: String?): String? {
        if (existing.isNullOrEmpty()) return scanned
        if (scanned.isNullOrEmpty()) return existing
        if (isMediaStoreAlbumArt(scanned) && !isMediaStoreAlbumArt(existing)) return existing
        return scanned
    }

    fun sanitizeFilename(input: String): String = input.replace(reserved, "_").replace(spaces, " ").jsTrim().take(160)

    data class Parsed(val title: String, val artist: String, val album: String)

    fun parseFilename(filename: String): Parsed {
        if (filename.isEmpty()) return Parsed("Unknown Title", "Unknown Artist", "Unknown Album")
        val name = filename.replace(extension, "")
        val parts = separator.split(name).map { it.jsTrim() }.filter { it.isNotEmpty() }
        if (parts.size >= 3) return Parsed(parts.drop(2).joinToString(" - "), parts[0], parts[1])
        if (parts.size == 2) {
            return if (numeric.matches(parts[0])) Parsed(parts[1], "Unknown Artist", "Unknown Album")
            else Parsed(parts[1], parts[0], "Unknown Album")
        }
        val title = name.replace(trackNumberPrefix, "").replace(leadingDashes, "").jsTrim()
        return Parsed(title.ifEmpty { name }, "Unknown Artist", "Unknown Album")
    }

    /** `enrichTrackFromUri`: fill unknown title/artist/album from the file name, then the parent folder. */
    fun enrich(track: Track, source: String): Track {
        val filename = source.substringAfterLast('/')
        val name = filename.replace(extension, "")
        val parsed = parseFilename(filename)
        val pathParts = source.split('/')
        val parentFolder = if (pathParts.size > 2) pathParts[pathParts.size - 2] else null
        val album = when {
            track.album != "Unknown Album" && track.album != "Unknown" -> track.album
            parsed.album != "Unknown Album" -> parsed.album
            !parentFolder.isNullOrEmpty() && parentFolder.lower() !in genericParentFolders -> decode(parentFolder)
            else -> "Unknown Album"
        }
        return track.copy(
            title = if (track.title == name || track.title == "Unknown" || track.title == "Unknown Title") parsed.title else track.title,
            artist = if (track.artist == "Unknown Artist" || track.artist == "Unknown") parsed.artist else track.artist,
            album = album,
        )
    }

    private fun filenameKey(value: String) = value.replace(extension, "").lower().jsTrim()

    /** Filename (without extension) -> the stored track, because MediaStore and SAF give one file different URIs. */
    fun existingByFilename(current: List<Track>): Map<String, Track> {
        val result = LinkedHashMap<String, Track>()
        for (t in current) {
            if (t.uri.isEmpty()) continue
            val fromUri = filenameKey(decode(t.uri).substringAfterLast('/'))
            if (fromUri.length > 5 && !numeric.matches(fromUri)) result[fromUri] = t
            if (t.artist.isNotEmpty() && t.album.isNotEmpty() && t.title.isNotEmpty() && t.artist != "Unknown Artist" && t.album != "Unknown Album") {
                val reconstructed = sanitizeFilename("${t.artist} - ${t.album} - ${t.title}").lower().jsTrim()
                if (reconstructed.isNotEmpty()) result[reconstructed] = t
            }
        }
        return result
    }

    private fun <T> T?.orStored(other: T?, isSet: (T) -> Boolean): T? = if (this != null && isSet(this)) this else other
    private fun String?.orStored(other: String?) = orStored(other) { it.isNotEmpty() }
    private fun Int?.orStored(other: Int?) = orStored(other) { it != 0 }
    private fun Long?.orStored(other: Long?) = orStored(other) { it != 0L }

    private fun quote(value: String) = buildString {
        append('"')
        for (c in value) when {
            c == '"' -> append("\\\"")
            c == '\\' -> append("\\\\")
            c == '\n' -> append("\\n")
            c == '\r' -> append("\\r")
            c == '\t' -> append("\\t")
            c < ' ' -> append("\\u%04x".format(c.code))
            else -> append(c)
        }
        append('"')
    }

    /** The track to store for one scanned file, or null when it is junk. */
    fun reconcile(scanned: ScannedTrack, existing: Map<String, Track>): Track? {
        val track = scanned.track
        val filename = scanned.filename?.takeIf { it.isNotEmpty() }
        if (isLikelyJunk(track, filename)) return null
        val enriched = enrich(track, filename ?: track.uri).let {
            // `_filename` stays on stored local tracks: playback rebuilds a file:// URI from it when content:// fails.
            if (filename == null) it else it.copy(extensions = it.extensions + (FILENAME_KEY to quote(filename)))
        }
        if (isLikelyJunk(enriched, filename)) return null

        val key = filenameKey(filename ?: decode(track.uri).substringAfterLast('/'))
        val stored = if (key.isNotEmpty()) existing[key] else null
        if (stored == null) return enriched

        val artwork = resolveArtwork(enriched.artwork, stored.artwork)
        return enriched.copy(
            title = if (hasMeaningfulValue(stored.title)) stored.title else enriched.title,
            artist = if (hasMeaningfulValue(stored.artist)) stored.artist else enriched.artist,
            album = if (hasMeaningfulValue(stored.album)) stored.album else enriched.album,
            artwork = artwork,
            artworkThumb = if (artwork == stored.artwork) stored.artworkThumb else null,
            year = enriched.year.orStored(stored.year),
            trackNumber = enriched.trackNumber.orStored(stored.trackNumber),
            genre = enriched.genre.orStored(stored.genre),
            quality = enriched.quality.orStored(stored.quality),
            sampleRate = enriched.sampleRate.orStored(stored.sampleRate),
            bitDepth = enriched.bitDepth.orStored(stored.bitDepth),
            codec = enriched.codec.orStored(stored.codec),
            source = enriched.source.orStored(stored.source),
            tidalId = enriched.tidalId.orStored(stored.tidalId),
            tidalAlbumId = enriched.tidalAlbumId.orStored(stored.tidalAlbumId),
            favorite = stored.favorite,
        )
    }

    /** Reconciles a whole scan. Result order is first-seen order; a later file with the same id replaces the value in place. */
    fun reconcileAll(current: List<Track>, scanned: List<ScannedTrack>): List<Track> {
        val existing = existingByFilename(current)
        val result = LinkedHashMap<String, Track>()
        for (file in scanned) reconcile(file, existing)?.let { result[it.id] = it }
        return result.values.toList()
    }
}
